using System.Reflection;
using System.Xml.Linq;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the dependency direction: Infrastructure -> Application -> Domain.</summary>
public sealed class LayerDependencyTests
{
    private const string Prefix = "PaymentAuthorization.";

    private static readonly string[] TechnicalAssemblies =
    [
        "System.Net.Http", "System.Data", "System.Data.Common", "System.Data.SqlClient",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "System.IO.FileSystem",
        "System.Net.Sockets", "System.Net.Requests", "Newtonsoft.Json",
    ];

    public static TheoryData<string, string[]> Layers => new()
    {
        { "Domain", ["Application", "Infrastructure"] },
        { "Application", ["Infrastructure"] },
    };

    [Theory]
    [MemberData(nameof(Layers))]
    public void A_layer_does_not_reference_layers_outside_of_it(string layer, string[] forbidden)
    {
        var referenced = ReferencedNames(layer);

        foreach (var other in forbidden)
            Assert.DoesNotContain(Prefix + other, referenced);
    }

    [Theory]
    [InlineData("Domain")]
    [InlineData("Application")]
    public void Business_layers_do_not_use_technical_libraries(string layer)
    {
        var offending = ReferencedNames(layer).Intersect(TechnicalAssemblies).ToArray();

        Assert.Empty(offending);
    }

    [Theory]
    [InlineData("Domain", new string[0])]
    [InlineData("Application", new[] { "Domain" })]
    public void Project_files_only_reference_allowed_layers(string layer, string[] allowed)
    {
        var csproj = Path.Combine(SolutionRoot(), "src", Prefix + layer, Prefix + layer + ".csproj");
        var references = XDocument.Load(csproj).Descendants()
            .Where(e => e.Name.LocalName is "ProjectReference" or "PackageReference")
            .Select(e => (string?)e.Attribute("Include") ?? "")
            .Select(i => Path.GetFileNameWithoutExtension(i.Replace('\\', '/')))
            .ToArray();

        Assert.Equal(allowed.Select(a => Prefix + a).Order(), references.Order());
    }

    private static string[] ReferencedNames(string layer) =>
        Assembly.Load(Prefix + layer).GetReferencedAssemblies().Select(a => a.Name!).ToArray();

    private static string SolutionRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "PaymentAuthorization.slnx")))
            dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("Solution root not found.");
    }
}
